    case KoreaHerald = 'korea_herald';
    case KoreaTimes = 'korea_times';
    case KoreaJoongangDaily = 'korea_joongang_daily';
    case YonhapEn = 'yonhap_en';
    case DailyNk = 'daily_nk';
    case BusinessKorea = 'business_korea';
    case KoreaItTimes = 'korea_it_times';
    case KoreaTechToday = 'korea_tech_today';
    case Dawn = 'dawn';
    case TheNews = 'the_news';
    case ExpressTribune = 'express_tribune';
    case PakObserver = 'pak_observer';
    case BusinessRecorder = 'business_recorder';
    case ProfitPakistanToday = 'profit_pakistan_today';
    case GeoNews = 'geo_news';
    case AryNews = 'ary_news';
    case SuchTv = 'such_tv';
    case Propakistani = 'propakistani';
    case UltimaHora = 'ultima_hora';
    case LaNacionPy = 'la_nacion_py';
    case CincoDias = 'cinco_dias';

    /**
     * Display name of the outlet.
     */
    public function label(): string
    {
        return SourceMap::LABELS[$this->value];
    }

    /**
     * Collectors that offer this source.
     *
     * @return list<Collector>
     */
    public function collectors(): array
    {
        $collectors = [];

        foreach (SourceMap::BY_COLLECTOR as $collector => $sources) {
            if (in_array($this->value, $sources, true)) {
                $collectors[] = Collector::from($collector);
            }
        }

        return $collectors;
    }

    /**
     * The language of the outlet as a source group, e.g. `SourceGroup::Spanish`.
     */
    public function language(): SourceGroup
    {
        return SourceLanguages::of($this);
    }
}
